package ais.action.master.generic.v2.adapter;
import java.util.ArrayList;import java.util.Calendar;import java.util.Date;import java.util.List;import org.hibernate.Session;import org.hibernate.criterion.Restrictions;import ais.action.master.generic.v2.GenericCrudDefinition;import ais.action.master.generic.v2.GenericCrudException;import ais.action.master.generic.v2.GenericCrudRequestContext;import ais.database.model.GeneralValueObject;import ais.database.model.Tbmuser;import ais.database.model.rab.Kalender;
/** CRUD rab.Kalender (master hari libur), terpisah dari KalenderAction yang sebenarnya mengelola Acara. */
@SuppressWarnings({"rawtypes","unchecked"})public final class KalenderHariLiburGenericCrudAdapter extends GenericCrudAutoEntityAdapter{
 public KalenderHariLiburGenericCrudAdapter(){super(Kalender.class,false,null,true);}public void configure(GenericCrudDefinition d){d.setDisplayName("Kalender Hari Libur");d.setDefaultSortProperty("tanggal");d.setDefaultSortAscending(false);d.setDefaultPageSize(50);d.setMaxPageSize(366);d.setImportEnabled(true);}
 public GeneralValueObject createNew(GenericCrudRequestContext c)throws Exception{Kalender v=(Kalender)super.createNew(c);v.setTanggal(new Date());v.setHariLibur(Boolean.valueOf(isWeekend(v.getTanggal())));return v;}
 public void beforeSave(Session s,GeneralValueObject target,GenericCrudRequestContext c)throws Exception{Kalender v=(Kalender)target;if(v.getNama()==null||v.getNama().trim().length()==0)throw new GenericCrudException(400,"CALENDAR_NAME_REQUIRED","Nama kalender wajib diisi.");if(v.getTanggal()==null)throw new GenericCrudException(400,"CALENDAR_DATE_REQUIRED","Tanggal wajib diisi.");Object duplicate=s.createCriteria(Kalender.class).add(Restrictions.eq("tanggal",v.getTanggal())).add(v.getId()==null?Restrictions.sqlRestriction("1=1"):Restrictions.ne("id",v.getId())).setMaxResults(1).uniqueResult();if(duplicate!=null)throw new GenericCrudException(409,"CALENDAR_DATE_EXISTS","Tanggal tersebut sudah terdaftar pada kalender.");if(v.getHariLibur()==null)v.setHariLibur(Boolean.valueOf(isWeekend(v.getTanggal())));Tbmuser u=c==null?null:c.getUser();if(u!=null){v.setOleh(u.getUserNama());v.setOlehId(u.getUserId());}super.beforeSave(s,target,c);}
 private static boolean isWeekend(Date d){Calendar c=Calendar.getInstance();c.setTime(d);int x=c.get(Calendar.DAY_OF_WEEK);return x==Calendar.SATURDAY||x==Calendar.SUNDAY;}public List getNaturalKeyProperties(){List v=new ArrayList();v.add("tanggal");return v;}}
